package cart

type Item struct {
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items []Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: []Item{},
	}
}

func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	for i := range c.items {
		if c.items[i].Name == name {
			c.items[i].Quantity += quantity
			return
		}
	}
	c.items = append(c.items, Item{Name: name, Price: price, Quantity: quantity})
}

func (c *ShoppingCart) RemoveItem(name string) {
	for i := range c.items {
		if c.items[i].Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return
		}
	}
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = []Item{}
}

func (c *ShoppingCart) GetItems() []Item {
	result := make([]Item, len(c.items))
	copy(result, c.items)
	return result
}

func (c *ShoppingCart) ApplyDiscount(percent float64) float64 {
	total := c.GetTotal()
	return total * (1 - percent/100)
}
